"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[612],{4612:(e,a,n)=>{n.d(a,{W:()=>i});var t=n(6578);let o=[{id:1,title:"Living Ecosystems",subtitle:"Life in the UAE Desert & Sea",icon:"\uD83C\uDF3F",xpReward:120,landmark:"Ras Al Khor Wildlife Sanctuary",landmarkIcon:"\uD83E\uDDA9",status:"completed",stars:3,color:"#009A44",lessons:[{id:"s4-1-1",title:"What is an Ecosystem?",content:"An **ecosystem** is a community of living things and their environment working together!\n\nIn the UAE, we have amazing ecosystems:\n\n\uD83C\uDFDC️ **Desert Ecosystem** — Home to the Arabian oryx, sand gazelle, and the ghaf tree\n\uD83C\uDF0A **Marine Ecosystem** — The Arabian Gulf is rich with fish, dolphins, and dugongs\n\uD83C\uDF34 **Mangrove Ecosystem** — Abu Dhabi's mangroves shelter baby fish and birds\n\n**Living things** (plants, animals) + **Non-living things** (sun, water, sand) = **Ecosystem**!",visual:"ecosystem",xp:40},{id:"s4-1-2",title:"Food Chains in the Desert",content:"A **food chain** shows who eats whom in an ecosystem!\n\n\uD83C\uDF31 **Producers** — Plants make food from sunlight (ghaf tree, desert grass)\n\uD83D\uDC1B **Primary Consumers** — Animals that eat plants (locusts, rabbits)\n\uD83E\uDD85 **Secondary Consumers** — Animals that eat plant-eaters (falcons, foxes)\n\n**UAE Desert Food Chain:**\nGhaf Tree \uD83C\uDF33 → Sand Gazelle \uD83E\uDD8C → Arabian Wolf \uD83D\uDC3A → Decomposers \uD83C\uDF42\n\nThe **Peregrine Falcon** \uD83E\uDD85 is at the top of many UAE food chains!",visual:"foodchain",xp:40},{id:"s4-1-3",title:"Protecting UAE Wildlife",content:"The UAE is a world leader in **wildlife conservation**!\n\n\uD83E\uDD81 **Arabian Oryx** — Once extinct in the wild, brought back through UAE's breeding programs\n\uD83D\uDC22 **Hawksbill Sea Turtles** — Protected nesting sites across UAE beaches\n\uD83C\uDF34 **Mangrove Planting** — UAE planted over 100 million mangrove trees\n\nThe **Ghaf Tree** \uD83C\uDF33 is the UAE's national tree — it survives extreme desert heat and provides shade, food, and shelter.\n\nYou can help by: **reducing waste**, **saving water**, and **respecting wildlife**!",visual:"scramble",scrambleWord:"ECOSYSTEM",scrambleHint:"The word for a community of living things and their environment",xp:40}],quiz:[{type:"matching",q:"Match each UAE ecosystem to its key species:",pairs:[{left:"Desert",right:"Arabian Oryx \uD83E\uDD81"},{left:"Marine",right:"Hawksbill Turtle \uD83D\uDC22"},{left:"Mangrove",right:"Flamingo \uD83E\uDDA9"}],explanation:"Different animals are specially adapted to each UAE ecosystem. The oryx survives desert heat, turtles nest on UAE beaches, and flamingos flock to mangrove mudflats!"},{q:"What is an ecosystem?",options:["Only living things","Only non-living things","Living things and their environment","Just plants and animals"],correct:2,explanation:"An ecosystem includes BOTH living things AND non-living things like sun, water, and soil."},{q:"What is the UAE's national tree?",options:["Palm Tree","Ghaf Tree","Mangrove","Date Palm"],correct:1,explanation:"The Ghaf Tree is the UAE's national tree — it survives the harsh desert!"},{q:"Which animal was brought back from extinction by UAE breeding programs?",options:["Arabian Wolf","Peregrine Falcon","Arabian Oryx","Sand Gazelle"],correct:2,explanation:"The Arabian Oryx was once extinct in the wild but was saved by UAE conservation efforts!"},{q:"In a food chain, what are producers?",options:["Animals that eat meat","Plants that make food from sunlight","Animals that eat plants","Decomposers"],correct:1,explanation:"Producers are plants that create food using sunlight through photosynthesis."},{q:"What type of ecosystem has mangrove trees?",options:["Desert ecosystem","Mountain ecosystem","Marine/coastal ecosystem","Forest ecosystem"],correct:2,explanation:"Mangroves grow in coastal/marine ecosystems where fresh and salt water meet."}]},{id:2,title:"Energy Around Us",subtitle:"Heat, Light & Solar Power",icon:"☀️",xpReward:150,landmark:"Mohammed bin Rashid Solar Park",landmarkIcon:"\uD83C\uDF1E",status:"completed",stars:2,color:"#C8A840",lessons:[{id:"s4-2-1",title:"Forms of Energy",content:"**Energy** is the ability to do work! It comes in many forms:\n\n☀️ **Light Energy** — From the sun, lightbulbs, fires\n\uD83D\uDD25 **Heat Energy** — From the sun, cooking, engines\n⚡ **Electrical Energy** — Powers our homes and devices\n\uD83D\uDD0A **Sound Energy** — Music, speech, thunder\n\uD83C\uDFC3 **Kinetic Energy** — Moving objects (a running child, waves)\n\n**In the UAE**, the strong desert sun provides massive amounts of **solar energy**!",visual:"energy",xp:50},{id:"s4-2-2",title:"The UAE's Solar Revolution",content:"The UAE is building the world's LARGEST solar power stations!\n\n\uD83C\uDF1E **Mohammed bin Rashid Al Maktoum Solar Park** in Dubai — Will generate 5,000 MW of clean energy\n☀️ **Noor Abu Dhabi** — One of the world's largest single solar farms\n\n**How Solar Panels Work:**\n1. Sunlight hits the solar panel\n2. Electrons in the panel get energized\n3. This creates electricity ⚡\n4. Electricity powers homes and schools!\n\nThe UAE aims to get **44% of its energy from clean sources** by 2050!",visual:"solar",xp:50},{id:"s4-2-3",title:"Saving Energy at Home",content:"We can all help save energy and protect our planet!\n\n\uD83D\uDCA1 **Switch off lights** when you leave a room\n❄️ **Set AC to 24\xb0C** — Each degree higher saves 6% energy\n\uD83D\uDEBF **Take shorter showers** — Heating water uses energy\n\uD83D\uDCF1 **Unplug chargers** when not in use\n\n**Did you know?** The UAE uses more energy per person than most countries because of the hot climate and AC. That's why saving energy is so important here!\n\n\uD83C\uDF3F The UAE's **Net Zero 2050** plan will make the country carbon-neutral!",visual:"saveenergy",xp:50}],quiz:[{q:"What form of energy comes from the sun?",options:["Only heat energy","Only light energy","Both heat and light energy","Sound energy"],correct:2,explanation:"The sun gives us both heat energy AND light energy!"},{q:"What is kinetic energy?",options:["Energy from heat","Energy of moving objects","Energy from electricity","Energy stored in food"],correct:1,explanation:"Kinetic energy is the energy of movement — a running falcon has kinetic energy!"},{q:"What is the UAE's goal for clean energy by 2050?",options:["100%","25%","44%","10%"],correct:2,explanation:"The UAE aims to get 44% of its energy from clean sources by 2050."},{q:"How do solar panels create electricity?",options:["By burning fuel","By heating water","When sunlight energizes electrons in the panel","By spinning turbines"],correct:2,explanation:"Solar panels work when sunlight hits them and energizes electrons, creating electrical current."},{q:"What is the recommended AC temperature to save energy in the UAE?",options:["18\xb0C","20\xb0C","24\xb0C","30\xb0C"],correct:2,explanation:"Setting AC to 24\xb0C is recommended — each degree lower uses 6% more energy!"}]},{id:3,title:"Space & Our Solar System",subtitle:"UAE's Journey to Mars",icon:"\uD83D\uDE80",xpReward:180,landmark:"UAE Space Centre",landmarkIcon:"\uD83D\uDEF8",status:"active",stars:0,color:"#CE1126",lessons:[{id:"s4-3-1",title:"Our Solar System",content:"Our **solar system** has 8 planets orbiting the Sun!\n\n☀️ **Sun** → ☿ Mercury → ♀️ Venus → \uD83C\uDF0D Earth → ♂️ Mars → ♃ Jupiter → ♄ Saturn → ♅ Uranus → ♆ Neptune\n\n**Our Earth:**\n• The only planet known to have life\n• Has liquid water, atmosphere, and the right temperature\n• Orbits the Sun in **365.25 days** (one year)\n\n**The Moon** orbits Earth and takes **29.5 days** for one full orbit!",visual:"solarsystem",xp:60},{id:"s4-3-2",title:"UAE's Hope Probe to Mars",content:"In 2020, the UAE launched the **Hope Probe (مسبار الأمل)** — the Arab world's first Mars mission!\n\n\uD83D\uDE80 **Launch:** July 20, 2020 from Japan\n\uD83D\uDD34 **Arrived at Mars:** February 9, 2021 — coinciding with UAE's 50th National Day year!\n\uD83C\uDF1F **Mission:** Study Mars's weather and atmosphere\n\n**Amazing facts:**\n• Hope Probe travels at **121,000 km/h**\n• Mars is up to **400 million km** from Earth\n• It takes **13 minutes** for signals to travel from Mars to Earth\n\nThe UAE became the **5th country** to reach Mars orbit!",visual:"hopemission",xp:60},{id:"s4-3-3",title:"Stars and Constellations",content:'A **star** is a massive ball of hot gas that produces light and heat through nuclear fusion.\n\n⭐ Our **Sun** is a medium-sized star — there are billions bigger!\n\n**Constellations** are patterns of stars that ancient peoples named:\n• **Orion** (the Hunter)\n• **Scorpius** (the Scorpion) — visible from UAE!\n• **Ursa Major** (the Great Bear / Big Dipper)\n\n\uD83C\uDF19 **Arabic astronomy:** Many star names come from Arabic!\n• **Betelgeuse** — from Arabic "Ibt al-Jawzā\'"\n• **Aldebaran** — from Arabic "Al-Dabarān"\n\nArab astronomers were among the greatest in history!',visual:"stars",xp:60}],quiz:[{q:"How many planets are in our solar system?",options:["7","8","9","10"],correct:1,explanation:"There are 8 planets: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune."},{q:"What was the UAE's first space mission called?",options:["Falcon 1","Hope Probe","Emirates Star","Al-Amal"],correct:1,explanation:"The UAE's Hope Probe (مسبار الأمل, meaning 'probe of hope') was the Arab world's first Mars mission!"},{q:"In what year did the Hope Probe arrive at Mars?",options:["2020","2021","2022","2019"],correct:1,explanation:"The Hope Probe arrived at Mars on February 9, 2021."},{q:"How long does Earth take to orbit the Sun?",options:["24 hours","29.5 days","365.25 days","12 months exactly"],correct:2,explanation:"Earth takes 365.25 days (about 365 and a quarter days) to orbit the Sun — that's why we have leap years!"},{q:"What language gave us many star names?",options:["Latin","Greek","Arabic","Sanskrit"],correct:2,explanation:"Arabic astronomers named many stars — names like Betelgeuse, Aldebaran, and Rigel all come from Arabic!"}]},{id:4,title:"Animals & Habitats",subtitle:"Creatures of the Arabian Peninsula",icon:"\uD83E\uDD81",xpReward:200,landmark:"Al Ain Zoo",landmarkIcon:"\uD83D\uDC18",status:"locked",stars:0,color:"#3B82F6",lessons:[],quiz:[{q:"What adaptation helps a camel survive the desert?",options:["Thick fur for cold nights only","Humps store water","Humps store fat for energy, not water","Large ears to hear predators"],correct:2,explanation:"Camel humps store FAT (not water!) which can be converted to energy and water. They also have other adaptations!"},{q:"What is the UAE's national animal?",options:["Camel","Arabian Oryx","Peregrine Falcon","Arabian Horse"],correct:1,explanation:"The Arabian Oryx is the UAE's national animal — it was once extinct in the wild but was saved by conservation!"},{q:"What do we call animals that are active at night?",options:["Diurnal","Nocturnal","Hibernating","Migratory"],correct:1,explanation:"Nocturnal animals are active at night — many UAE desert animals are nocturnal to avoid the daytime heat!"},{q:"Which sea creature is called the 'sea cow'?",options:["Whale shark","Dolphin","Dugong","Manta ray"],correct:2,explanation:"The Dugong is called the 'sea cow' — it's a gentle marine mammal that feeds on sea grass in UAE waters!"},{q:"What is a group of flamingos called?",options:["A flock","A flamboyance","A pack","A colony"],correct:1,explanation:"A group of flamingos is called a 'flamboyance'! Pink flamingos visit Ras Al Khor in Dubai every year."}]},{id:5,title:"Plants & Photosynthesis",subtitle:"Green Life in a Desert World",icon:"\uD83C\uDF31",xpReward:220,landmark:"Dubai Miracle Garden",landmarkIcon:"\uD83C\uDF38",status:"locked",stars:0,color:"#8B5CF6",lessons:[],quiz:[]},{id:6,title:"Earth & Weather",subtitle:"Seasons, Clouds & Climate",icon:"\uD83C\uDF0D",xpReward:300,landmark:"Jebel Jais Mountain",landmarkIcon:"⛰️",status:"locked",stars:0,color:"#C8A840",lessons:[],quiz:[]}],s=[{id:1,title:"Cells & Life",subtitle:"The Building Blocks of All Living Things",icon:"\uD83D\uDD2C",xpReward:150,landmark:"Khalifa University",landmarkIcon:"\uD83C\uDF93",status:"completed",stars:3,color:"#009A44",lessons:[{id:"s8-1-1",title:"Cell Theory",content:"All living things are made of **cells** — the basic unit of life!\n\n**Three principles of Cell Theory:**\n1. All living things are made of one or more cells\n2. The cell is the basic unit of structure and function\n3. All cells come from pre-existing cells\n\n**Two main types of cells:**\n• **Prokaryotic** — No nucleus (bacteria, archaea)\n• **Eukaryotic** — Has a nucleus (plants, animals, fungi)\n\nA single **drop of blood** contains about **5 million red blood cells**! \uD83E\uDE78",visual:"cell",xp:50},{id:"s8-1-2",title:"Cell Organelles",content:"Cell organelles are like the **organs of a cell** — each has a specific job!\n\n\uD83E\uDDE0 **Nucleus** — Control center; contains DNA\n⚡ **Mitochondria** — Powerhouse; produces energy (ATP)\n\uD83C\uDFED **Ribosomes** — Make proteins\n\uD83D\uDCE6 **Golgi Apparatus** — Packages and ships proteins\n\uD83D\uDCA7 **Vacuole** — Storage (water, waste)\n\uD83C\uDF3F **Chloroplasts** — In plant cells; perform photosynthesis\n\uD83D\uDEE1️ **Cell Wall** — In plant cells; rigid outer support\n\n**Remember:** Animal cells have mitochondria but NOT chloroplasts or cell walls!",visual:"cell_interactive",xp:50},{id:"s8-1-3",title:"Cell Division",content:"Cells reproduce through **cell division**!\n\n**Mitosis** (for growth and repair):\nOne cell → Two identical daughter cells\n\n**Steps: PMAT**\n• **P**rophase — Chromosomes become visible\n• **M**etaphase — Chromosomes line up in the middle\n• **A**naphase — Chromosomes are pulled apart\n• **T**elophase — Two new nuclei form\n\n**Meiosis** (for reproduction):\nOne cell → Four sex cells (sperm/eggs) with half the chromosomes\n\n\uD83C\uDF31 A healthy adult human produces **3.8 million new red blood cells** every second!",visual:"celldivision",xp:50}],quiz:[{type:"matching",q:"Match each cell organelle with its function:",pairs:[{left:"Nucleus",right:"Contains DNA and controls cell activity"},{left:"Mitochondria",right:"Produces energy (ATP) for the cell"},{left:"Vacuole",right:"Stores water, waste and nutrients"},{left:"Cell Membrane",right:"Controls what enters and leaves the cell"}],explanation:"Each organelle has a unique job — like organs in a body! The nucleus is the brain, mitochondria are the batteries, vacuoles are the storage room, and the membrane is the security door."},{q:"What is the powerhouse of the cell?",options:["Nucleus","Ribosome","Mitochondria","Vacuole"],correct:2,explanation:"Mitochondria produce ATP (energy) — they are the powerhouse of the cell!"},{q:"Which organelle contains the cell's DNA?",options:["Mitochondria","Nucleus","Golgi Apparatus","Ribosome"],correct:1,explanation:"The nucleus is the control center of the cell and contains DNA."},{q:"What organelle do ONLY plant cells have?",options:["Mitochondria","Nucleus","Ribosomes","Chloroplasts"],correct:3,explanation:"Chloroplasts are found only in plant cells — they perform photosynthesis to make food from sunlight!"},{q:"What type of cell division produces sex cells?",options:["Mitosis","Meiosis","Binary fission","Budding"],correct:1,explanation:"Meiosis produces sex cells (sperm and eggs) with half the normal number of chromosomes."},{q:"According to cell theory, where do new cells come from?",options:["Spontaneous generation","Pre-existing cells","Non-living matter","Chemical reactions"],correct:1,explanation:"Cell theory states: all cells come from pre-existing cells!"}]},{id:2,title:"Matter & Atoms",subtitle:"Chemistry of the Universe",icon:"⚗️",xpReward:200,landmark:"ADNOC Research Centre",landmarkIcon:"\uD83C\uDFED",status:"completed",stars:2,color:"#C8A840",lessons:[{id:"s8-2-1",title:"Atoms & the Periodic Table",content:"**Atoms** are the smallest particles of an element that still have the properties of that element.\n\n**Parts of an atom:**\n• ⊕ **Protons** — Positive charge (in nucleus)\n• ○ **Neutrons** — No charge (in nucleus)\n• ⊖ **Electrons** — Negative charge (orbit the nucleus)\n\n**The Periodic Table** organizes all 118 known elements!\n• Elements in the same **column** have similar properties\n• The **atomic number** = number of protons\n\n\uD83D\uDD2C The UAE uses chemistry in oil refining, medicine, and water desalination!",visual:"atoms",xp:65},{id:"s8-2-2",title:"States of Matter",content:"Matter exists in **three main states**: solid, liquid, and gas!\n\n\uD83E\uDDCA **Solid** — Fixed shape and volume; particles tightly packed\n\uD83D\uDCA7 **Liquid** — Fixed volume, takes the shape of its container\n\uD83D\uDCA8 **Gas** — No fixed shape or volume; particles spread out\n\n**Changes of state:**\n• Melting \uD83E\uDDCA→\uD83D\uDCA7 (solid to liquid)\n• Freezing \uD83D\uDCA7→\uD83E\uDDCA (liquid to solid)\n• Evaporation \uD83D\uDCA7→\uD83D\uDCA8 (liquid to gas)\n• Condensation \uD83D\uDCA8→\uD83D\uDCA7 (gas to liquid)\n\n\uD83C\uDF0A The UAE desalinates **seawater into drinking water** using evaporation and condensation — providing 42% of the UAE's drinking water!",visual:"matter",xp:65},{id:"s8-2-3",title:"Chemical Reactions",content:"A **chemical reaction** is a process where substances change into different substances!\n\n**Signs of a chemical reaction:**\n• Color change\n• Gas production (bubbles)\n• Temperature change\n• Formation of precipitate\n\n**Reactants** → **Products**\n\n**Law of Conservation of Mass:**\nMatter cannot be created or destroyed — atoms just rearrange!\n\n**Example:** Water formation\n2H₂ + O₂ → 2H₂O\n\n\uD83D\uDEE2️ **UAE connection:** Crude oil refining is a series of chemical reactions that produces petrol, diesel, and plastics!",visual:"reactions",xp:70}],quiz:[{q:"What particle in an atom has a POSITIVE charge?",options:["Electron","Neutron","Proton","Nucleus"],correct:2,explanation:"Protons carry a positive charge and are found in the nucleus of the atom."},{q:"What is the process of liquid turning into gas called?",options:["Freezing","Condensation","Evaporation","Melting"],correct:2,explanation:"Evaporation is when a liquid turns into gas — how the UAE desalinates water!"},{q:"What law states that matter cannot be created or destroyed?",options:["Newton's Law","Law of Conservation of Mass","Mendel's Law","Ohm's Law"],correct:1,explanation:"The Law of Conservation of Mass: in a chemical reaction, matter is neither created nor destroyed, just rearranged."},{q:"Which state of matter has a FIXED volume but NO fixed shape?",options:["Solid","Liquid","Gas","Plasma"],correct:1,explanation:"Liquids have a fixed volume but take the shape of their container."},{q:"In a chemical reaction, what are the starting materials called?",options:["Products","Reactants","Catalysts","Compounds"],correct:1,explanation:"Reactants are the starting materials in a chemical reaction. They become the products."}]},{id:3,title:"Forces & Motion",subtitle:"Physics in Action",icon:"⚡",xpReward:250,landmark:"Yas Marina Circuit",landmarkIcon:"\uD83C\uDFCE️",status:"active",stars:0,color:"#CE1126",lessons:[{id:"s8-3-1",title:"Newton's Laws of Motion",content:"**Sir Isaac Newton** discovered three laws that describe how objects move!\n\n**1st Law (Inertia):** An object stays at rest or moving in a straight line unless a force acts on it.\n• Example: A parked car stays parked — until you push it!\n\n**2nd Law:** Force = Mass \xd7 Acceleration (F = ma)\n• A heavier car needs MORE force to accelerate!\n\n**3rd Law:** For every action, there is an equal and opposite reaction.\n• A rocket pushes gas DOWN → gas pushes rocket UP! \uD83D\uDE80\n• UAE's Hope Probe used this law to launch to Mars!",visual:"newton",xp:80},{id:"s8-3-2",title:"Types of Forces",content:"**Forces** are pushes or pulls that can change an object's motion!\n\n\uD83C\uDF0D **Gravity** — Pulls all masses together (keeps us on Earth)\n\uD83E\uDDF2 **Magnetic force** — Attraction/repulsion between magnets\n⚡ **Electrostatic force** — Between charged particles\n\uD83D\uDCA8 **Air resistance/Drag** — Friction with air\n\uD83C\uDFCE️ **Normal force** — Surface pushing back\n\n**Balanced forces** → No change in motion\n**Unbalanced forces** → Object accelerates\n\n**Speed vs Velocity:**\n• Speed = distance \xf7 time\n• Velocity = speed + direction",visual:"forces",xp:85},{id:"s8-3-3",title:"Energy Transfer & Work",content:"**Work** is done when a force causes an object to move:\n**Work = Force \xd7 Distance** (W = F \xd7 d)\n\nUnit: **Joule (J)**\n\n**Types of mechanical energy:**\n• **Kinetic Energy (KE)** = \xbdmv\xb2 (energy of motion)\n• **Potential Energy (PE)** = mgh (stored energy)\n\n**Energy conservation:** Total energy stays the same — it just changes form!\n\n\uD83C\uDFA2 **Example at Yas Island:**\nAt the top of a roller coaster → High PE, Low KE\nAt the bottom → Low PE, High KE\n\nAll the PE has been converted to KE (speed)! \uD83C\uDF89",visual:"energy8",xp:85}],quiz:[{q:"Which of Newton's laws states F = ma?",options:["First Law","Second Law","Third Law","Law of Gravity"],correct:1,explanation:"Newton's Second Law: Force = Mass \xd7 Acceleration (F = ma)"},{q:"What is the unit of work?",options:["Newton","Watt","Joule","Metre"],correct:2,explanation:"Work is measured in Joules (J). W = Force \xd7 Distance."},{q:"A rocket pushes gas downward. The gas pushes the rocket upward. Which law is this?",options:["First Law","Second Law","Third Law","Law of Inertia"],correct:2,explanation:"Newton's Third Law: every action has an equal and opposite reaction!"},{q:"At the top of a roller coaster, what type of energy is greatest?",options:["Kinetic energy","Potential energy","Electrical energy","Chemical energy"],correct:1,explanation:"At the top, the object is high up = maximum potential energy. As it falls, PE converts to KE (speed)."},{q:"What is velocity?",options:["Speed only","Speed with direction","Distance divided by time","Force times mass"],correct:1,explanation:"Velocity is speed WITH a direction — e.g., 60 km/h NORTH is velocity; 60 km/h alone is speed."}]},{id:4,title:"Earth Science",subtitle:"Rocks, Plates & Natural Forces",icon:"\uD83C\uDF0B",xpReward:280,landmark:"Hajar Mountains",landmarkIcon:"⛰️",status:"locked",stars:0,color:"#3B82F6",lessons:[],quiz:[{q:"What are the three types of rocks?",options:["Hard, soft, and medium","Igneous, sedimentary, and metamorphic","Volcanic, river, and desert","Black, white, and grey"],correct:1,explanation:"The three rock types are igneous (from magma), sedimentary (from compressed layers), and metamorphic (changed by heat/pressure)."},{q:"What causes earthquakes?",options:["Heavy rain","Tectonic plate movement","Volcanic eruptions only","Ocean currents"],correct:1,explanation:"Earthquakes are caused by the sudden movement of tectonic plates along fault lines."},{q:"The Hajar Mountains in UAE were formed by:",options:["River erosion","Tectonic plate collision","Wind erosion","Volcanic activity"],correct:1,explanation:"The Hajar Mountains were formed millions of years ago when tectonic plates collided."},{q:"What is the layer of the Earth that we live on?",options:["Core","Mantle","Crust","Lithosphere"],correct:2,explanation:"We live on the Earth's crust — the thin outer layer that makes up the continents and ocean floors."},{q:"What is the process of water moving through the environment called?",options:["Carbon cycle","Water cycle","Nitrogen cycle","Rock cycle"],correct:1,explanation:"The water cycle describes how water evaporates, condenses, and falls as precipitation continuously."}]},{id:5,title:"Genetics & Heredity",subtitle:"DNA and the Code of Life",icon:"\uD83E\uDDEC",xpReward:320,landmark:"Genomics Abu Dhabi",landmarkIcon:"\uD83C\uDFE5",status:"locked",stars:0,color:"#8B5CF6",lessons:[],quiz:[]},{id:6,title:"Science Challenge",subtitle:"Master of Science",icon:"\uD83C\uDFC6",xpReward:500,landmark:"UAE Science Museum",landmarkIcon:"\uD83D\uDD2D",status:"locked",stars:0,color:"#C8A840",lessons:[],quiz:[]}],i={grade8math:t.e$,grade8science:s,grade4science:o,grade4math:t.e$}},6578:(e,a,n)=>{n.d(a,{Hz:()=>o,IH:()=>s,e$:()=>r,hc:()=>i,on:()=>t});let t=2e3,o=15,s=[{id:"grade8-math",grade:"Grade 8",gradeNum:8,subject:"Mathematics",icon:"\uD83D\uDCD0",color:"#009A44",banner:"\uD83D\uDD4C",arabicTitle:"الجبر",subtitle:"Algebra Adventure",description:"Master algebra with UAE-themed problems",dataKey:"grade8math"},{id:"grade8-science",grade:"Grade 8",gradeNum:8,subject:"Science",icon:"⚗️",color:"#CE1126",banner:"\uD83D\uDD2C",arabicTitle:"العلوم",subtitle:"Science Explorer",description:"Explore cells, atoms, forces and more",dataKey:"grade8science"},{id:"grade4-math",grade:"Grade 4",gradeNum:4,subject:"Mathematics",icon:"\uD83D\uDD22",color:"#C8A840",banner:"\uD83C\uDF34",arabicTitle:"الرياضيات",subtitle:"Math Quest",description:"Fractions, geometry and problem solving",dataKey:"grade4math"},{id:"grade4-science",grade:"Grade 4",gradeNum:4,subject:"Science",icon:"\uD83C\uDF3F",color:"#3B82F6",banner:"\uD83E\uDD85",arabicTitle:"علوم الطبيعة",subtitle:"Nature Explorer",description:"Ecosystems, energy, space and wildlife",dataKey:"grade4science"}],i={first_lesson:{name:"First Step",icon:"\uD83C\uDF1F",desc:"Completed your first lesson",color:"#FFD700"},quiz_master:{name:"Quiz Master",icon:"\uD83C\uDFC6",desc:"Got 5 stars on a quiz",color:"#C8A840"},streak_7:{name:"7-Day Streak",icon:"\uD83D\uDD25",desc:"Studied 7 days in a row",color:"#CE1126"},algebra_hero:{name:"Algebra Hero",icon:"\uD83E\uDD85",desc:"Completed all algebra modules",color:"#009A44"},problem_solver:{name:"Problem Solver",icon:"\uD83E\uDDEE",desc:"Solved 50 problems",color:"#9B59B6"},speed_demon:{name:"Speed Demon",icon:"⚡",desc:"Finished a quiz in under 2 minutes",color:"#3498DB"}},r=[{id:1,title:"What is Algebra?",subtitle:"The Language of Mathematics",icon:"\uD83D\uDCD6",xpReward:150,landmark:"Burj Khalifa",landmarkIcon:"\uD83C\uDFD7️",status:"completed",stars:3,color:"#009A44",lessons:[{id:"1-1",title:"Introduction to Algebra",content:'Algebra is a branch of mathematics that uses symbols and letters to represent numbers and quantities in formulas and equations. The word "algebra" comes from the Arabic word **"Al-Jabr"** (الجبر), meaning "reunion of broken parts." It was pioneered by the great Muslim mathematician **Muhammad ibn Musa al-Khwarizmi** from the House of Wisdom in Baghdad!',visual:"book",xp:50},{id:"1-2",title:"Why Learn Algebra?",content:"Algebra is used everywhere in the UAE and beyond:\n\n\uD83C\uDFD7️ **Architecture**: Engineers used algebra to design the Burj Khalifa\n\uD83D\uDE80 **Space**: UAE's Hope Probe mission to Mars relied on algebraic equations\n\uD83D\uDCB0 **Business**: Calculating profits and losses in Dubai's markets\n\uD83C\uDF0A **Engineering**: Designing the Palm Jumeirah required algebra",visual:"applications",xp:50},{id:"1-3",title:"Variables and Constants",content:"In algebra, we use:\n\n**Variables**: Letters like x, y, n that represent unknown values\n**Constants**: Fixed numbers that don't change\n\nExample: If Ahmed has **x** dirhams in his wallet and spends **15** dirhams, he has **x - 15** dirhams left.\n\nHere:\n• **x** = variable (unknown amount)\n• **15** = constant (fixed number)",visual:"variables",xp:50}],quiz:[{type:"matching",q:"Match each algebra term to its meaning:",pairs:[{left:"Variable",right:"A letter representing an unknown value (e.g. x)"},{left:"Constant",right:"A fixed number that does not change (e.g. 7)"},{left:"Al-Jabr",right:'Arabic word that gave us the word "Algebra"'}],explanation:"Algebra was invented by Al-Khwarizmi, using Arabic words. Variables like x can change, while constants like 7 always stay the same!"},{q:"What does the word 'Algebra' come from?",options:["Greek 'algebras'","Arabic 'Al-Jabr'","Latin 'algebra'","Persian 'al-jabra'"],correct:1,explanation:"Algebra comes from the Arabic word 'Al-Jabr' (الجبر), meaning 'reunion of broken parts'!"},{q:"Which of these is a variable?",options:["15","42","x","100"],correct:2,explanation:"Variables are letters (like x) that represent unknown values."},{q:"In '3x + 7', what is the constant?",options:["3","x","7","3x"],correct:2,explanation:"7 is a constant — it's a fixed number that doesn't change."},{q:"Who pioneered Algebra?",options:["Ibn Sina","Al-Khwarizmi","Al-Biruni","Al-Farabi"],correct:1,explanation:"Muhammad ibn Musa al-Khwarizmi from the House of Wisdom in Baghdad is the father of Algebra!"},{q:"In the equation y = 2x + 5, how many variables are there?",options:["1","2","3","0"],correct:1,explanation:"There are 2 variables: x and y. The numbers 2 and 5 are constants."}]},{id:2,title:"Algebraic Expressions",subtitle:"Building Blocks of Equations",icon:"\uD83D\uDD27",xpReward:200,landmark:"Sheikh Zayed Grand Mosque",landmarkIcon:"\uD83D\uDD4C",status:"completed",stars:2,color:"#C8A840",lessons:[{id:"2-1",title:"Writing Expressions",content:"An **algebraic expression** is a combination of variables, constants, and operations.\n\n**Examples:**\n• 3x + 5 (three times x, plus five)\n• 2y - 7 (two times y, minus seven)\n• 4a + 3b - 1\n\n**Parts of an expression:**\n• **Term**: Each separate part (3x, 5, 2y are all terms)\n• **Coefficient**: The number in front of a variable (3 in 3x)\n• **Like terms**: Terms with the same variable (3x and 5x are like terms)",visual:"expression",xp:65},{id:"2-2",title:"Simplifying Expressions",content:"We can **simplify** expressions by combining like terms!\n\n**Example:** Simplify 3x + 2x + 7\n\nStep 1: Find like terms → 3x and 2x are like terms\nStep 2: Combine them → 3x + 2x = 5x\nStep 3: Result → **5x + 7** ✓\n\n**Another example:**\n4y + 3 + 2y - 1\n= (4y + 2y) + (3 - 1)\n= **6y + 2** ✓",visual:"simplify",xp:65},{id:"2-3",title:"Evaluating Expressions",content:"To **evaluate** an expression, substitute the given value of the variable!\n\n**Example:** Evaluate 2x + 3 when x = 4\n\nStep 1: Replace x with 4 → 2(4) + 3\nStep 2: Multiply → 8 + 3\nStep 3: Add → **11** ✓\n\n\uD83C\uDFC5 **UAE Challenge:** Ahmed earns (5h + 20) dirhams where h = hours worked. If he works 6 hours, how much does he earn?\n\n5(6) + 20 = 30 + 20 = **50 dirhams** \uD83D\uDCB0",visual:"evaluate",xp:70}],quiz:[{q:"What is the coefficient in 7x?",options:["x","7","7x","1"],correct:1,explanation:"The coefficient is the number in front of the variable. In 7x, the coefficient is 7."},{q:"Simplify: 4x + 3x",options:["7x\xb2","7x","12x","x⁷"],correct:1,explanation:"4x + 3x = 7x. We add the coefficients (4+3=7) and keep the variable."},{q:"Evaluate 3x - 2 when x = 5",options:["13","7","17","10"],correct:0,explanation:"3(5) - 2 = 15 - 2 = 13"},{q:"Which are like terms?",options:["3x and 3y","5x and 2x","4x and 4","x\xb2 and x"],correct:1,explanation:"Like terms have the same variable. 5x and 2x both have 'x'."},{q:"Simplify: 5a + 2b + 3a - b",options:["8a + b","8ab","8a - b","10ab"],correct:0,explanation:"5a + 3a = 8a, and 2b - b = b. So the answer is 8a + b."}]},{id:3,title:"Linear Equations",subtitle:"Solving for the Unknown",icon:"⚖️",xpReward:250,landmark:"Dubai Creek",landmarkIcon:"⛵",status:"active",stars:0,color:"#CE1126",lessons:[{id:"3-1",title:"What is an Equation?",content:"An **equation** is a mathematical statement that two expressions are equal, using the **= sign**.\n\nThink of an equation like a balance scale ⚖️ — both sides must be equal!\n\n**Examples:**\n• x + 3 = 7 (what value of x makes this true?)\n• 2y = 10\n• 3x - 1 = 8\n\n**Solution**: The value that makes the equation true\n• x + 3 = 7 → x = 4 ✓ (because 4 + 3 = 7)",visual:"balance",xp:80},{id:"3-2",title:"Solving One-Step Equations",content:"**Key Rule**: Whatever you do to one side, do to the other!\n\n**Addition/Subtraction:**\nx + 5 = 12\nx + 5 **- 5** = 12 **- 5**\nx = **7** ✓\n\n**Multiplication/Division:**\n3x = 18\n3x **\xf7 3** = 18 **\xf7 3**\nx = **6** ✓\n\n\uD83C\uDF1F **Think of it like**: If you take 5 dirhams from Ahmed's wallet (x + 5), you need to add 5 back to find the original amount!",visual:"onestep",xp:85},{id:"3-3",title:"Two-Step Equations",content:"For two-step equations, work **backwards** using inverse operations!\n\n**Example:** Solve 2x + 3 = 11\n\nStep 1: Subtract 3 from both sides\n2x + 3 - 3 = 11 - 3\n2x = 8\n\nStep 2: Divide both sides by 2\n2x \xf7 2 = 8 \xf7 2\n**x = 4** ✓\n\nCheck: 2(4) + 3 = 8 + 3 = 11 ✓ \uD83C\uDF89",visual:"twostep",xp:85}],quiz:[{q:"Solve: x + 7 = 15",options:["x = 8","x = 22","x = 7","x = 15"],correct:0,explanation:"x + 7 = 15 → x = 15 - 7 = 8"},{q:"Solve: 4x = 20",options:["x = 80","x = 16","x = 24","x = 5"],correct:3,explanation:"4x = 20 → x = 20 \xf7 4 = 5"},{q:"Solve: 2x + 1 = 9",options:["x = 4","x = 5","x = 3","x = 8"],correct:0,explanation:"2x = 9 - 1 = 8, then x = 8 \xf7 2 = 4"},{q:"Solve: x - 6 = 3",options:["x = -3","x = 9","x = 3","x = 18"],correct:1,explanation:"x - 6 = 3 → x = 3 + 6 = 9"},{q:"Solve: 3x - 2 = 13",options:["x = 5","x = 4","x = 6","x = 3"],correct:0,explanation:"3x = 13 + 2 = 15, then x = 15 \xf7 3 = 5"}]},{id:4,title:"Word Problems",subtitle:"Real-Life Algebra",icon:"\uD83C\uDF0D",xpReward:300,landmark:"Louvre Abu Dhabi",landmarkIcon:"\uD83C\uDFDB️",status:"locked",stars:0,color:"#3B82F6",lessons:[],quiz:[{q:"Ahmed has x dirhams. He earns 50 more and now has 200. Find x.",options:["x = 150","x = 250","x = 100","x = 200"],correct:0,explanation:"x + 50 = 200 → x = 150 dirhams"},{q:"A rectangle's length is 2 more than its width (w). If perimeter is 28, find w.",options:["w = 6","w = 8","w = 7","w = 5"],correct:0,explanation:"2(w + w + 2) = 28 → 4w + 4 = 28 → w = 6"},{q:"3 identical books cost 45 dirhams. Write an equation.",options:["x + 3 = 45","3x = 45","x - 3 = 45","x/45 = 3"],correct:1,explanation:"If each book costs x, then 3x = 45, so x = 15 dirhams each."},{q:"Fatima is 3 years older than her brother. Together their ages equal 25. How old is Fatima?",options:["11","14","13","12"],correct:1,explanation:"x + (x+3) = 25 → 2x + 3 = 25 → x = 11, Fatima = 14"},{q:"A camel travels at 12 km/h. Write an expression for distance after h hours.",options:["12 + h","12h","h/12","12 - h"],correct:1,explanation:"Distance = speed \xd7 time = 12h"}]},{id:5,title:"Inequalities",subtitle:"Greater Than, Less Than",icon:"\uD83D\uDCCA",xpReward:350,landmark:"Yas Island",landmarkIcon:"\uD83C\uDFA2",status:"locked",stars:0,color:"#8B5CF6",lessons:[],quiz:[]},{id:6,title:"Final Challenge",subtitle:"Master of Algebra",icon:"\uD83C\uDFC6",xpReward:500,landmark:"UAE Space Centre",landmarkIcon:"\uD83D\uDE80",status:"locked",stars:0,color:"#C8A840",lessons:[],quiz:[]}]}}]);